import {validateTransaction} from './core.js';
export const VERSION='rev02.3';
export const DATA_KEYS=['transactions','monthlyBudget','theme'];
export const SNAPSHOTS_KEY='jodjai-snapshots-v1';
export function capture(storage){return Object.fromEntries(DATA_KEYS.map(key=>[key,storage.getItem(key)]));}
export function snapshots(storage){const raw=storage.getItem(SNAPSHOTS_KEY);if(raw===null)return [];const list=JSON.parse(raw);if(!Array.isArray(list)||list.some(s=>!s||typeof s.createdAt!=='string'||!s.records||DATA_KEYS.some(k=>s.records[k]!==null&&typeof s.records[k]!=='string')))throw Error('สำเนาในเครื่องอ่านไม่ได้ กรุณาส่งออกข้อมูลก่อนแก้ไข');return list;}
export function checkpoint(storage){const records=capture(storage),list=snapshots(storage);if(list.length&&JSON.stringify(list.at(-1).records)===JSON.stringify(records))return;const entry={createdAt:new Date().toISOString(),records};const next=[...list,entry];const kept=next.length<=8?next:[next[0],...next.slice(-7)];const raw=JSON.stringify(kept);storage.setItem(SNAPSHOTS_KEY,raw);if(storage.getItem(SNAPSHOTS_KEY)!==raw)throw Error('บันทึกสำเนาในเครื่องไม่สำเร็จ');}
export function guardedWrite(storage,key,value){if(!DATA_KEYS.includes(key))throw Error('Unsupported data key');checkpoint(storage);storage.setItem(key,value);if(storage.getItem(key)!==value)throw Error('ตรวจสอบข้อมูลหลังบันทึกไม่สำเร็จ');}
function payload(value){return {app:value.app,schema:value.schema,createdAt:value.createdAt,origin:value.origin,version:value.version,records:Object.fromEntries(DATA_KEYS.map(k=>[k,value.records?.[k]]))};}
async function hash(value){const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value));return [...new Uint8Array(bytes)].map(b=>b.toString(16).padStart(2,'0')).join('');}
export async function makeBackup(records,origin){const body=payload({app:'JodJai',schema:1,createdAt:new Date().toISOString(),origin,version:VERSION,records});return {...body,sha256:await hash(JSON.stringify(body))};}
export function validateRecords(records){if(!records||DATA_KEYS.some(k=>records[k]!==null&&typeof records[k]!=='string'))throw Error('รูปแบบข้อมูลสำรองไม่ถูกต้อง');let txs=[];try{txs=records.transactions===null?[]:JSON.parse(records.transactions);}catch{throw Error('รายการรายจ่ายในไฟล์อ่านไม่ได้');}if(!Array.isArray(txs)||txs.length>100000||txs.some(tx=>!validateTransaction(tx)))throw Error('พบรายการที่ไม่ถูกต้อง ยกเลิกการนำเข้าโดยไม่แก้ข้อมูลเดิม');if(records.monthlyBudget!==null&&(!records.monthlyBudget.trim()||!Number.isFinite(Number(records.monthlyBudget))||Number(records.monthlyBudget)<0||Number(records.monthlyBudget)>999999999))throw Error('งบประมาณในไฟล์ไม่ถูกต้อง');if(records.theme!==null&&!['light','dark'].includes(records.theme))throw Error('ธีมในไฟล์ไม่ถูกต้อง');return txs.map(tx=>({...tx,...validateTransaction(tx)}));}
export async function readBackup(text){if(text.length>10*1024*1024)throw Error('ไฟล์ต้องมีขนาดไม่เกิน 10 MB');let data;try{data=JSON.parse(text);}catch{throw Error('อ่านไฟล์ JSON ไม่สำเร็จ');}if(!data||data.app!=='JodJai'||data.schema!==1||typeof data.createdAt!=='string'||!Number.isFinite(Date.parse(data.createdAt))||typeof data.origin!=='string'||typeof data.version!=='string'||typeof data.sha256!=='string')throw Error('ไฟล์นี้ไม่ใช่ข้อมูลสำรองจดจ่ายที่รองรับ');if(await hash(JSON.stringify(payload(data)))!==data.sha256)throw Error('ไฟล์สำรองเปลี่ยนแปลงหรือเสียหาย ยกเลิกการนำเข้า');validateRecords(data.records);return data;}
function comparable(tx){return JSON.stringify([String(tx.id),tx.date,tx.category,tx.amount,tx.note??'']);}
export async function mergeRecords(existing,incoming){const normalize=tx=>{const value=validateTransaction(tx);if(!value)throw Error('รายการที่นำเข้าหรือข้อมูลปัจจุบันไม่ถูกต้อง');return {...tx,...value};};existing=existing.map(normalize);incoming=incoming.map(normalize);const merged=[...existing],seen=new Map(existing.map(tx=>[String(tx.id),tx]));let added=0,duplicates=0,conflicts=0;for(const row of incoming){const tx={...row};const old=seen.get(String(tx.id));if(old){if(comparable(old)===comparable(tx)){duplicates++;continue;}conflicts++;const suffix=await hash(comparable(tx));const base=String(tx.id).slice(0,25)+'-recovered-'+suffix;tx.id=base;let index=0;while(seen.has(String(tx.id))&&comparable({...seen.get(String(tx.id)),id:row.id})!==comparable(row))tx.id=base+'-'+(++index);if(seen.has(String(tx.id))){duplicates++;continue;}}seen.set(String(tx.id),tx);merged.push(tx);added++;}return {transactions:merged,added,duplicates,conflicts};}
